typedef struct decode_case {
    const char *name;
    cdisasm_mode mode;
    uint8_t bytes[CDISASM_MAX_INSTRUCTION_SIZE];
    size_t size;
    const char *mnemonic;
    uint32_t groups;
    uint64_t target;
    int has_target;
} decode_case;

static int failures = 0;

#define EXPECT(condition) \
    do { \
        if (!(condition)) { \
            fprintf(stderr, "%s:%d: expectation failed: %s\n", __FILE__, __LINE__, #condition); \
            ++failures; \
        } \
    } while (0)

#define CASE(mode_, name_, mnemonic_, operands_, groups_, target_, has_target_, ...) \
    {name_, mode_, {__VA_ARGS__}, sizeof((uint8_t[]){__VA_ARGS__}), mnemonic_, groups_, target_, has_target_}

