static void test_x86_name_ids(void)
{
    const size_t manifest_count =
        sizeof(x86_name_id_manifest) / sizeof(x86_name_id_manifest[0]);
    size_t index;

    EXPECT(sizeof(cdisasm_x86_name_id) == 2);
    EXPECT(sizeof(cdisasm_name_id) == sizeof(cdisasm_x86_name_id));
    EXPECT(CDISASM_X86_NAME_INVALID == CDISASM_X86_NAME_NONE);
    EXPECT(CDISASM_X86_NAME_FIRST == CDISASM_X86_NAME_AAA);
    EXPECT(CDISASM_X86_NAME_VGETEXPBF16 < CDISASM_X86_NAME_COUNT);
    EXPECT(CDISASM_X86_NAME_ENDING == CDISASM_X86_NAME_COUNT);
    EXPECT(CDISASM_X86_NAME_ICEBP == CDISASM_X86_NAME_INT1);
    EXPECT(CDISASM_X86_NAME_LOADALLD == CDISASM_X86_NAME_LOADALL);
    EXPECT(CDISASM_X86_NAME_SETALC == CDISASM_X86_NAME_SALC);
    EXPECT(manifest_count
        == (size_t)CDISASM_X86_NAME_VGETEXPBF16 + 1u);
    EXPECT(sizeof(legacy_name_id_manifest) / sizeof(legacy_name_id_manifest[0])
        == manifest_count);

    for (index = 0; index < manifest_count; ++index) {
        EXPECT(x86_name_id_manifest[index] == (cdisasm_x86_name_id)index);
        EXPECT(legacy_name_id_manifest[index] == x86_name_id_manifest[index]);
    }
}

