static void test_x86_group_ids(void)
{
    static const cdisasm_x86_group_id retired_group_ids[] = {
        CDISASM_X86_GROUP_3DNOW,
        CDISASM_X86_GROUP_3DNOW_EXT,
        CDISASM_X86_GROUP_XOP,
        CDISASM_X86_GROUP_FMA4,
        CDISASM_X86_GROUP_TBM,
        CDISASM_X86_GROUP_LWP,
        CDISASM_X86_GROUP_MPX,
    };
    size_t index;

    EXPECT(sizeof(cdisasm_x86_group_id) == 2);
    EXPECT(CDISASM_X86_GROUP_FIRST == CDISASM_X86_GROUP_I86);
    EXPECT(CDISASM_X86_GROUP_LAST == CDISASM_X86_GROUP_WRMSRNS);
    EXPECT(sizeof(x86_group_id_manifest) / sizeof(x86_group_id_manifest[0])
        == CDISASM_X86_GROUP_ENQCMD + 1u);
    EXPECT(CDISASM_X86_GROUP_ACE_1 == CDISASM_X86_GROUP_ENQCMD + 1u);
    EXPECT(CDISASM_X86_GROUP_COUNT == 323u);
    for (index = 0;
         index < sizeof(x86_group_id_manifest)
             / sizeof(x86_group_id_manifest[0]);
         ++index) {
        EXPECT(x86_group_id_manifest[index] == (cdisasm_x86_group_id)index);
    }
    for (index = 0;
         index < sizeof(retired_group_ids) / sizeof(retired_group_ids[0]);
         ++index) {
        EXPECT(retired_group_ids[index] >= CDISASM_X86_GROUP_FIRST);
        EXPECT(retired_group_ids[index] <= CDISASM_X86_GROUP_LAST);
    }

    EXPECT(CDISASM_X86_GROUP_3DNOWEXT == CDISASM_X86_GROUP_3DNOW_EXT);
    EXPECT(CDISASM_X86_GROUP_X86_64 == CDISASM_X86_GROUP_AMD64);
    EXPECT(CDISASM_X86_GROUP_SYSENTER == CDISASM_X86_GROUP_SEP);
    EXPECT(CDISASM_X86_GROUP_BMI == CDISASM_X86_GROUP_BMI1);
    EXPECT(CDISASM_X86_GROUP_AVX512 == CDISASM_X86_GROUP_AVX512F);
    EXPECT(CDISASM_X86_GROUP_AVX10 == CDISASM_X86_GROUP_AVX10_1);
    EXPECT(CDISASM_X86_GROUP_APX == CDISASM_X86_GROUP_APX_F);
}

