static void test_x86_reg_ids(void)
{
    size_t index;

    EXPECT(sizeof(cdisasm_x86_reg_id) == 2);
    EXPECT(sizeof(cdisasm_register_id) == sizeof(cdisasm_x86_reg_id));
    EXPECT(CDISASM_X86_REG_INVALID == CDISASM_X86_REG_NONE);
    EXPECT(CDISASM_X86_REG_FIRST == CDISASM_X86_REG_AL);
    EXPECT(CDISASM_X86_REG_LAST == CDISASM_X86_REG_BSR0);
    EXPECT(CDISASM_X86_REG_ENDING == CDISASM_X86_REG_COUNT);
    EXPECT(sizeof(x86_reg_id_manifest) / sizeof(x86_reg_id_manifest[0])
        == CDISASM_X86_REG_COUNT - 2u);
    EXPECT(sizeof(legacy_reg_id_manifest) / sizeof(legacy_reg_id_manifest[0])
        == CDISASM_X86_REG_COUNT - 2u);

    for (index = 0; index < CDISASM_X86_REG_COUNT - 2u; ++index) {
        cdisasm_x86_reg_id expected = (cdisasm_x86_reg_id)
            (index < 78u ? index : index + 2u);

        EXPECT(x86_reg_id_manifest[index] == expected);
        EXPECT(x86_reg_id_manifest[index] != UINT16_C(78));
        EXPECT(x86_reg_id_manifest[index] != UINT16_C(79));
        EXPECT(legacy_reg_id_manifest[index] == x86_reg_id_manifest[index]);
    }
}

