    EXPECT(CDISASM_OPERAND_IMMEDIATE == 2);
    EXPECT(CDISASM_OPERAND_MEMORY == 3);
    EXPECT(CDISASM_OPERAND_ACCESS_NONE == 0);
    EXPECT(CDISASM_OPERAND_ACCESS_READ_WRITE == 3);
