/* 0xfe and 0xff select operand-size-dependent environment/state widths. */
static const uint8_t x87_expected_memory_sizes[8][8] = {
    {4, 4, 4, 4, 4, 4, 4, 4},
    {4, 0, 4, 4, 0xfe, 2, 0xfe, 2},
    {4, 4, 4, 4, 4, 4, 4, 4},
    {4, 4, 4, 4, 0, 10, 0, 10},
    {8, 8, 8, 8, 8, 8, 8, 8},
    {8, 8, 8, 8, 0xff, 0, 0xff, 2},
    {2, 2, 2, 2, 2, 2, 2, 2},
    {2, 2, 2, 2, 10, 8, 10, 8}
};

static const uint8_t x87_expected_memory_write_masks[8] = {
    0x00, 0xcc, 0x00, 0x8e, 0x00, 0xce, 0x00, 0xce
};

static cdisasm_x86_name_id x87_expected_name(
    uint8_t opcode,
    uint8_t modrm)
{
    size_t index;

    if ((modrm >> 6) != 3) {
        return x87_expected_memory_names[opcode - 0xd8][(modrm >> 3) & 7];
    }
    for (index = 0;
         index < sizeof(x87_expected_register_ranges)
            / sizeof(x87_expected_register_ranges[0]);
         ++index) {
        const x87_expected_range *range =
            &x87_expected_register_ranges[index];

        if (range->opcode == opcode
            && modrm >= range->first_modrm
            && modrm <= range->last_modrm) {
            return range->name_id;
        }
    }
    return CDISASM_X86_NAME_NONE;
}

static uint8_t x87_expected_memory_size(
    cdisasm_mode mode,
    unsigned int opcode_index,
    unsigned int extension)
{
    uint8_t size = x87_expected_memory_sizes[opcode_index][extension];

    if (size == 0xfe) {
        return mode == CDISASM_MODE_16 ? 14 : 28;
    }
    if (size == 0xff) {
        return mode == CDISASM_MODE_16 ? 94 : 108;
    }
    return size;
}

static void test_x87_exhaustive_classification(void)
{
    static const cdisasm_mode modes[] = {
        CDISASM_MODE_16, CDISASM_MODE_32, CDISASM_MODE_64
    };
    size_t mode_index;
    unsigned int opcode;
    unsigned int modrm;

    for (mode_index = 0;
         mode_index < sizeof(modes) / sizeof(modes[0]);
         ++mode_index) {
        for (opcode = 0xd8; opcode <= 0xdf; ++opcode) {
            for (modrm = 0; modrm <= UINT8_MAX; ++modrm) {
                uint8_t code[CDISASM_MAX_INSTRUCTION_SIZE] = {0};
                cdisasm_instruction first;
                cdisasm_instruction second;
                cdisasm_x86_name_id expected = x87_expected_name(
                    (uint8_t)opcode, (uint8_t)modrm);
                uint32_t first_size;
                uint32_t second_size;

                code[0] = (uint8_t)opcode;
                code[1] = (uint8_t)modrm;
                first_size = cdisasm_x86_decode(
                    CDISASM_CPU_X86, modes[mode_index], code, sizeof(code),
                    UINT64_C(0x1000), CDISASM_X86_TEST_ALL_FLAGS, &first);
                second_size = cdisasm_x86_decode(
                    CDISASM_CPU_X86, modes[mode_index], code, sizeof(code),
                    UINT64_C(0x1000), CDISASM_X86_TEST_ALL_FLAGS, &second);

                if (first_size != second_size
                    || memcmp(&first, &second, sizeof(first)) != 0) {
                    fprintf(stderr,
                        "x87 nondeterministic mode=%u bytes=%02x %02x\n",
                        (unsigned int)modes[mode_index], opcode, modrm);
                    ++failures;
                    continue;
                }
                if (expected == CDISASM_X86_NAME_NONE) {
                    if (first_size != 0
                        || !instruction_is_error_only(
                            &first, CDISASM_STATUS_INVALID_INSTRUCTION)) {
                        fprintf(stderr,
                            "x87 reserved accepted mode=%u bytes=%02x %02x "
                            "size=%u error=%u name=%u\n",
                            (unsigned int)modes[mode_index], opcode, modrm,
                            (unsigned int)first_size,
                            (unsigned int)first.last_error_id,
                            (unsigned int)first.name_id);
                        ++failures;
                    }
                    continue;
                }
                if (first_size == 0
                    || first.name_id != expected
                    || first.opcode_size != first_size
                    || !cdisasm_instruction_has_x86_group(
                        &first, CDISASM_X86_GROUP_X87)) {
                    fprintf(stderr,
                        "x87 valid rejected mode=%u bytes=%02x %02x "
                        "size=%u error=%u name=%u expected=%u\n",
                        (unsigned int)modes[mode_index], opcode, modrm,
                        (unsigned int)first_size,
                        (unsigned int)first.last_error_id,
                        (unsigned int)first.name_id,
                        (unsigned int)expected);
                    ++failures;
                    continue;
                }
                if ((modrm >> 6) != 3) {
                    unsigned int opcode_index = opcode - 0xd8;
                    unsigned int extension = (modrm >> 3) & 7;
                    cdisasm_operand_access expected_access =
                        (x87_expected_memory_write_masks[opcode_index]
                            & (UINT8_C(1) << extension)) != 0
                        ? CDISASM_OPERAND_ACCESS_WRITE
                        : CDISASM_OPERAND_ACCESS_READ;

                    if (first.operand_count != 1
                        || first.opcode[0].type != CDISASM_OPERAND_MEMORY
                        || first.opcode[0].size
                            != x87_expected_memory_size(
                                modes[mode_index], opcode_index, extension)
                        || first.opcode[0].access != expected_access) {
                        fprintf(stderr,
                            "x87 memory metadata mode=%u bytes=%02x %02x "
                            "count=%u type=%u width=%u access=%u\n",
                            (unsigned int)modes[mode_index], opcode, modrm,
                            (unsigned int)first.operand_count,
                            (unsigned int)first.opcode[0].type,
                            (unsigned int)first.opcode[0].size,
                            (unsigned int)first.opcode[0].access);
                        ++failures;
                    }
                } else {
                    unsigned int operand_index;

                    for (operand_index = 0;
                         operand_index < first.operand_count;
                         ++operand_index) {
                        const cdisasm_opcode *operand =
                            &first.opcode[operand_index];

                        if (operand->type != CDISASM_OPERAND_REGISTER
                            || operand->size == 0
                            || operand->access
                                == CDISASM_OPERAND_ACCESS_NONE) {
                            fprintf(stderr,
                                "x87 register metadata mode=%u "
                                "bytes=%02x %02x operand=%u\n",
                                (unsigned int)modes[mode_index], opcode,
                                modrm, operand_index);
                            ++failures;
                        }
                    }
                }
            }
        }
    }
}

static void test_x87_cpu_wait_and_metadata(void)
{
    typedef struct x87_cpu_case {
        const char *label;
        uint8_t opcode;
        uint8_t modrm;
        cdisasm_x86_name_id name_id;
    } x87_cpu_case;
    typedef struct x87_wait_alias_case {
        uint8_t opcode;
        uint8_t modrm;
        cdisasm_x86_name_id no_wait_name;
        cdisasm_x86_name_id wait_name;
    } x87_wait_alias_case;
    static const x87_wait_alias_case wait_aliases[] = {
        {0xdb, 0xe0, CDISASM_X86_NAME_FNENI, CDISASM_X86_NAME_FENI},
        {0xdb, 0xe1, CDISASM_X86_NAME_FNDISI, CDISASM_X86_NAME_FDISI},
        {0xdb, 0xe2, CDISASM_X86_NAME_FNCLEX, CDISASM_X86_NAME_FCLEX},
        {0xdb, 0xe3, CDISASM_X86_NAME_FNINIT, CDISASM_X86_NAME_FINIT},
        {0xdb, 0xe4, CDISASM_X86_NAME_FNSETPM, CDISASM_X86_NAME_FSETPM},
        {0xd9, 0x30, CDISASM_X86_NAME_FNSTENV,
            CDISASM_X86_NAME_FSTENV},
        {0xd9, 0x38, CDISASM_X86_NAME_FNSTCW, CDISASM_X86_NAME_FSTCW},
        {0xdd, 0x30, CDISASM_X86_NAME_FNSAVE, CDISASM_X86_NAME_FSAVE},
        {0xdd, 0x38, CDISASM_X86_NAME_FNSTSW, CDISASM_X86_NAME_FSTSW},
        {0xdf, 0xe0, CDISASM_X86_NAME_FNSTSW, CDISASM_X86_NAME_FSTSW}
    };
    static const x87_cpu_case compatibility_aliases[] = {
        {"FSTPNCE", 0xd9, 0xd9, CDISASM_X86_NAME_FSTPNCE},
        {"DC FCOM", 0xdc, 0xd1, CDISASM_X86_NAME_FCOM},
        {"DC FCOMP", 0xdc, 0xd9, CDISASM_X86_NAME_FCOMP},
        {"DD FXCH", 0xdd, 0xc9, CDISASM_X86_NAME_FXCH},
        {"DE FCOMP", 0xde, 0xd1, CDISASM_X86_NAME_FCOMP},
        {"DF FXCH", 0xdf, 0xc9, CDISASM_X86_NAME_FXCH},
        {"DF FSTP low", 0xdf, 0xd1, CDISASM_X86_NAME_FSTP},
        {"DF FSTP high", 0xdf, 0xd9, CDISASM_X86_NAME_FSTP}
    };
    static const uint8_t baseline[] = {0xd8, 0xc1};
    static const uint8_t ffreep[] = {0xdf, 0xc1};
    static const uint8_t fprem1[] = {0xd9, 0xf5};
    static const uint8_t fstpnce[] = {0xd9, 0xd9};
    static const uint8_t arpl[] = {0x63, 0xc0};
    static const uint8_t movzx[] = {0x0f, 0xb6, 0xc0};
    static const uint8_t fcmov[] = {0xda, 0xc1};
    static const uint8_t fisttp[] = {0xdb, 0x08};
    static const uint8_t fneni[] = {0xdb, 0xe0};
    static const uint8_t fndisi[] = {0xdb, 0xe1};
    static const uint8_t fnsetpm[] = {0xdb, 0xe4};
    static const uint8_t fnclex[] = {0xdb, 0xe2};
    static const uint8_t fclex[] = {0x9b, 0xdb, 0xe2};
    static const uint8_t fstcw[] = {0x9b, 0xd9, 0x38};
    static const uint8_t wait_only[] = {0x9b};
    static const uint8_t wait_before_regular[] = {0x9b, 0xd8, 0xc0};
    static const uint8_t x87_opcode_only[] = {0xd8};
    static const uint8_t x87_sib_only[] = {0xd8, 0x04};
    static const uint8_t x87_disp_short[] = {0xd8, 0x05, 0, 0, 0};
    static const uint8_t wait_disp_short[] = {0x9b, 0xd9, 0x35, 0};
    static const uint8_t reserved_register[] = {0xd9, 0xd1};
    static const uint8_t reserved_memory[] = {0xdb, 0x20};
    static const uint8_t env16[] = {0xd9, 0x20};
    static const uint8_t env16_override[] = {0x66, 0xd9, 0x20};
    static const uint8_t state16[] = {0xdd, 0x20};
    static const uint8_t env32_override[] = {0x66, 0xd9, 0x20};
    static const uint8_t state32_override[] = {0x66, 0xdd, 0x20};
    static const uint8_t register_arithmetic[] = {0xdc, 0xc3};
    static const uint8_t rep_x87[] = {0xf3, 0xd8, 0xc0};
    static const uint8_t repne_x87[] = {0xf2, 0xd8, 0xc0};
    static const uint8_t lock_x87[] = {0xf0, 0xd8, 0x00};
    static const uint8_t rex_x87_memory[] = {0x4d, 0xd8, 0x04, 0x24};
    static const uint8_t ineffective_rex_x87_memory[] = {
        0x4d, 0x66, 0xd8, 0x04, 0x24
    };
    static const uint8_t vex_x87[] = {0xc5, 0xf8, 0xd8, 0xc0};
    cdisasm_instruction instruction;
    size_t alias_index;

    expect_cpu_result("x87 rejected on plain 8086", CDISASM_CPU_8086,
        CDISASM_MODE_16, baseline, sizeof(baseline),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("x87 baseline on 8086 plus 8087",
        CDISASM_CPU_8086_8087,
        CDISASM_MODE_16, baseline, sizeof(baseline),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FADD);
    expect_cpu_result("x87 rejected on plain 80186", CDISASM_CPU_80186,
        CDISASM_MODE_16, baseline, sizeof(baseline),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("x87 baseline on 80186 plus 80187",
        CDISASM_CPU_80186_80187,
        CDISASM_MODE_16, baseline, sizeof(baseline),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FADD);
    expect_cpu_result("x87 rejected on plain 80286", CDISASM_CPU_80286,
        CDISASM_MODE_16, baseline, sizeof(baseline),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("x87 baseline on 80286 plus 80287",
        CDISASM_CPU_80286_80287,
        CDISASM_MODE_16, baseline, sizeof(baseline),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FADD);
    expect_cpu_result("x87 rejected on plain 80386", CDISASM_CPU_80386,
        CDISASM_MODE_32, baseline, sizeof(baseline),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("x87 baseline on 80386 plus 80387",
        CDISASM_CPU_80386_80387,
        CDISASM_MODE_32, baseline, sizeof(baseline),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FADD);
    expect_cpu_result("x87 integrated on 80486", CDISASM_CPU_80486,
        CDISASM_MODE_32, baseline, sizeof(baseline),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FADD);
    expect_cpu_result("FFREEP on 8087", CDISASM_CPU_8086_8087,
        CDISASM_MODE_16, ffreep, sizeof(ffreep),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FFREEP);
    expect_cpu_result("FFREEP on full-set 80187 profile",
        CDISASM_CPU_80186_80187,
        CDISASM_MODE_16, ffreep, sizeof(ffreep),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FFREEP);
    expect_cpu_result("FFREEP on 287 profile", CDISASM_CPU_80286_80287,
        CDISASM_MODE_16, ffreep, sizeof(ffreep),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FFREEP);
    expect_cpu_result("FPREM1 before 387", CDISASM_CPU_80286_80287,
        CDISASM_MODE_16, fprem1, sizeof(fprem1),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("FPREM1 on 387 profile", CDISASM_CPU_80386_80387,
        CDISASM_MODE_32, fprem1, sizeof(fprem1),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FPREM1);
    expect_cpu_result("FPREM1 on full-set 80187 profile",
        CDISASM_CPU_80186_80187,
        CDISASM_MODE_16, fprem1, sizeof(fprem1),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FPREM1);
    expect_cpu_result("FPREM1 on integrated 80486", CDISASM_CPU_80486,
        CDISASM_MODE_32, fprem1, sizeof(fprem1),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FPREM1);
    expect_cpu_result("FSTPNCE on 8087", CDISASM_CPU_8086_8087,
        CDISASM_MODE_16, fstpnce, sizeof(fstpnce),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FSTPNCE);
    expect_cpu_result("FSTPNCE on full-set 80187 profile",
        CDISASM_CPU_80186_80187,
        CDISASM_MODE_16, fstpnce, sizeof(fstpnce),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FSTPNCE);
    for (alias_index = 0;
         alias_index < sizeof(compatibility_aliases)
             / sizeof(compatibility_aliases[0]);
         ++alias_index) {
        const x87_cpu_case *alias = &compatibility_aliases[alias_index];
        uint8_t code[2] = {alias->opcode, alias->modrm};

        expect_cpu_result(alias->label, CDISASM_CPU_8086_8087,
            CDISASM_MODE_16, code, sizeof(code),
            CDISASM_STATUS_OK, alias->name_id);
        expect_cpu_result(alias->label, CDISASM_CPU_80286_80287,
            CDISASM_MODE_16, code, sizeof(code),
            CDISASM_STATUS_OK, alias->name_id);
    }
    expect_cpu_result("80187 profile does not add 80286 ISA",
        CDISASM_CPU_80186_80187,
        CDISASM_MODE_16, arpl, sizeof(arpl),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("80187 profile does not add 80386 ISA",
        CDISASM_CPU_80186_80187,
        CDISASM_MODE_16, movzx, sizeof(movzx),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("FCMOV before P6", CDISASM_CPU_PENTIUM,
        CDISASM_MODE_32, fcmov, sizeof(fcmov),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("FCMOV on P6", CDISASM_CPU_PENTIUM_PRO,
        CDISASM_MODE_32, fcmov, sizeof(fcmov),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FCMOVB);
    expect_cpu_result("FISTTP before SSE3", CDISASM_CPU_PENTIUM_4,
        CDISASM_MODE_32, fisttp, sizeof(fisttp),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("FISTTP with SSE3", CDISASM_CPU_PRESCOTT,
        CDISASM_MODE_32, fisttp, sizeof(fisttp),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FISTTP);
    expect_cpu_result("FNENI rejected without 8087", CDISASM_CPU_8086,
        CDISASM_MODE_16, fneni, sizeof(fneni),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("FNENI on 8087", CDISASM_CPU_8086_8087,
        CDISASM_MODE_16, fneni, sizeof(fneni),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FNENI);
    expect_cpu_result("FNDISI on 8087", CDISASM_CPU_8086_8087,
        CDISASM_MODE_16, fndisi, sizeof(fndisi),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FNDISI);
    expect_cpu_result("FNSETPM before 287", CDISASM_CPU_8086_8087,
        CDISASM_MODE_16, fnsetpm, sizeof(fnsetpm),
        CDISASM_STATUS_INVALID_INSTRUCTION, CDISASM_X86_NAME_NONE);
    expect_cpu_result("FNSETPM on 287", CDISASM_CPU_80286_80287,
        CDISASM_MODE_16, fnsetpm, sizeof(fnsetpm),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FNSETPM);
    expect_cpu_result("obsolete FNSETPM remains recognized on 80486",
        CDISASM_CPU_80486,
        CDISASM_MODE_32, fnsetpm, sizeof(fnsetpm),
        CDISASM_STATUS_OK, CDISASM_X86_NAME_FNSETPM);

    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        fnclex, sizeof(fnclex), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(fnclex));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FNCLEX);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_WAIT) == 0);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        fclex, sizeof(fclex), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(fclex));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FCLEX);
    EXPECT(instruction.opcode_flags == CDISASM_PREFIX_WAIT);
    EXPECT(instruction.encoding.prefix_size == 1);
    EXPECT(instruction.encoding.opcode_offset == 1);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        fstcw, sizeof(fstcw), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(fstcw));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FSTCW);
    EXPECT(instruction.opcode[0].size == 2);
    EXPECT(instruction.opcode[0].access == CDISASM_OPERAND_ACCESS_WRITE);

    for (alias_index = 0;
         alias_index < sizeof(wait_aliases) / sizeof(wait_aliases[0]);
         ++alias_index) {
        const x87_wait_alias_case *alias = &wait_aliases[alias_index];
        uint8_t no_wait_code[2] = {alias->opcode, alias->modrm};
        uint8_t wait_code[3] = {0x9b, alias->opcode, alias->modrm};

        EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
            no_wait_code, sizeof(no_wait_code), 0,
            CDISASM_X86_TEST_ALL_FLAGS, &instruction)
            == sizeof(no_wait_code));
        EXPECT(instruction.name_id == alias->no_wait_name);
        EXPECT((instruction.opcode_flags & CDISASM_PREFIX_WAIT) == 0);
        EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
            wait_code, sizeof(wait_code), 0,
            CDISASM_X86_TEST_ALL_FLAGS, &instruction)
            == sizeof(wait_code));
        EXPECT(instruction.name_id == alias->wait_name);
        EXPECT(instruction.opcode_flags == CDISASM_PREFIX_WAIT);
        EXPECT(instruction.encoding.prefix_size == 1);
        EXPECT(instruction.encoding.opcode_offset == 1);
    }
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        wait_only, sizeof(wait_only), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(wait_only));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_WAIT);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        wait_before_regular, sizeof(wait_before_regular), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 1);
    EXPECT(instruction.name_id == CDISASM_X86_NAME_WAIT);

    expect_failure("x87 opcode truncation", CDISASM_MODE_32,
        x87_opcode_only, sizeof(x87_opcode_only), CDISASM_STATUS_TRUNCATED);
    expect_failure("x87 SIB truncation", CDISASM_MODE_32,
        x87_sib_only, sizeof(x87_sib_only), CDISASM_STATUS_TRUNCATED);
    expect_failure("x87 displacement truncation", CDISASM_MODE_32,
        x87_disp_short, sizeof(x87_disp_short), CDISASM_STATUS_TRUNCATED);
    expect_failure("WAIT x87 displacement truncation", CDISASM_MODE_32,
        wait_disp_short, sizeof(wait_disp_short), CDISASM_STATUS_TRUNCATED);
    expect_failure("x87 reserved register", CDISASM_MODE_32,
        reserved_register, sizeof(reserved_register),
        CDISASM_STATUS_INVALID_INSTRUCTION);
    expect_failure("x87 reserved memory extension", CDISASM_MODE_32,
        reserved_memory, sizeof(reserved_memory),
        CDISASM_STATUS_INVALID_INSTRUCTION);

    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_16,
        env16, sizeof(env16), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(env16));
    EXPECT(instruction.opcode[0].size == 14);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_16,
        env16_override, sizeof(env16_override), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(env16_override));
    EXPECT(instruction.opcode[0].size == 28);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_16,
        state16, sizeof(state16), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(state16));
    EXPECT(instruction.opcode[0].size == 94);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        state16, sizeof(state16), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(state16));
    EXPECT(instruction.opcode[0].size == 108);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        env16, sizeof(env16), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(env16));
    EXPECT(instruction.opcode[0].size == 28);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        env32_override, sizeof(env32_override), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(env32_override));
    EXPECT(instruction.opcode[0].size == 14);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        state32_override, sizeof(state32_override), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(state32_override));
    EXPECT(instruction.opcode[0].size == 94);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        env32_override, sizeof(env32_override), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(env32_override));
    EXPECT(instruction.opcode[0].size == 14);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        state16, sizeof(state16), 0, CDISASM_X86_TEST_ALL_FLAGS,
        &instruction) == sizeof(state16));
    EXPECT(instruction.opcode[0].size == 108);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        register_arithmetic, sizeof(register_arithmetic), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(register_arithmetic));
    EXPECT(instruction.operand_count == 2);
    EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_ST3);
    EXPECT(instruction.opcode[0].size == 10);
    EXPECT(instruction.opcode[0].access
        == CDISASM_OPERAND_ACCESS_READ_WRITE);
    EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_ST0);
    EXPECT(instruction.opcode[1].access == CDISASM_OPERAND_ACCESS_READ);
    EXPECT(cdisasm_instruction_has_x86_group(
        &instruction, CDISASM_X86_GROUP_X87));

    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        fstpnce, sizeof(fstpnce), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == sizeof(fstpnce));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FSTPNCE);
    EXPECT(instruction.operand_count == 2);
    EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_ST1);
    EXPECT(instruction.opcode[0].access == CDISASM_OPERAND_ACCESS_WRITE);
    EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_ST0);
    EXPECT(instruction.opcode[1].access == CDISASM_OPERAND_ACCESS_READ);

    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        rep_x87, sizeof(rep_x87), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == sizeof(rep_x87));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FADD);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_REP) != 0);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_EFFECTIVE_REP) == 0);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        repne_x87, sizeof(repne_x87), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(repne_x87));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FADD);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_REPNE) != 0);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_EFFECTIVE_REPNE) == 0);
    expect_failure("LOCK x87", CDISASM_MODE_32,
        lock_x87, sizeof(lock_x87), CDISASM_STATUS_INVALID_INSTRUCTION);
    expect_failure("VEX cannot encode x87", CDISASM_MODE_64,
        vex_x87, sizeof(vex_x87), CDISASM_STATUS_INVALID_INSTRUCTION);

    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        rex_x87_memory, sizeof(rex_x87_memory), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(rex_x87_memory));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FADD);
    EXPECT(instruction.opcode[0].base_reg == CDISASM_X86_REG_R12);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_REX) != 0);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_REX_W) != 0);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        ineffective_rex_x87_memory, sizeof(ineffective_rex_x87_memory), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(ineffective_rex_x87_memory));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_FADD);
    EXPECT(instruction.opcode[0].base_reg == CDISASM_X86_REG_RSP);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_REX) != 0);
    EXPECT((instruction.opcode_flags & CDISASM_PREFIX_REX_W) == 0);
}

typedef struct vex_extra_test_case {
    cdisasm_x86_name_id name_id;
    uint8_t opcode;
    uint8_t prefix;
    uint8_t scalar;
    uint8_t integer;
} vex_extra_test_case;

static void test_vex_extra_opcodes(void)
{
    static const vex_extra_test_case cases[] = {
        {CDISASM_X86_NAME_VANDPS, 0x54, 0, 0, 0},
        {CDISASM_X86_NAME_VANDPD, 0x54, 1, 0, 0},
        {CDISASM_X86_NAME_VANDNPS, 0x55, 0, 0, 0},
        {CDISASM_X86_NAME_VANDNPD, 0x55, 1, 0, 0},
        {CDISASM_X86_NAME_VORPS, 0x56, 0, 0, 0},
        {CDISASM_X86_NAME_VORPD, 0x56, 1, 0, 0},
        {CDISASM_X86_NAME_VXORPS, 0x57, 0, 0, 0},
        {CDISASM_X86_NAME_VXORPD, 0x57, 1, 0, 0},
        {CDISASM_X86_NAME_VADDPS, 0x58, 0, 0, 0},
        {CDISASM_X86_NAME_VADDPD, 0x58, 1, 0, 0},
        {CDISASM_X86_NAME_VADDSS, 0x58, 2, 1, 0},
        {CDISASM_X86_NAME_VADDSD, 0x58, 3, 1, 0},
        {CDISASM_X86_NAME_VMULPS, 0x59, 0, 0, 0},
        {CDISASM_X86_NAME_VMULPD, 0x59, 1, 0, 0},
        {CDISASM_X86_NAME_VMULSS, 0x59, 2, 1, 0},
        {CDISASM_X86_NAME_VMULSD, 0x59, 3, 1, 0},
        {CDISASM_X86_NAME_VSUBPS, 0x5c, 0, 0, 0},
        {CDISASM_X86_NAME_VSUBPD, 0x5c, 1, 0, 0},
        {CDISASM_X86_NAME_VSUBSS, 0x5c, 2, 1, 0},
        {CDISASM_X86_NAME_VSUBSD, 0x5c, 3, 1, 0},
        {CDISASM_X86_NAME_VMINPS, 0x5d, 0, 0, 0},
        {CDISASM_X86_NAME_VMINPD, 0x5d, 1, 0, 0},
        {CDISASM_X86_NAME_VMINSS, 0x5d, 2, 1, 0},
        {CDISASM_X86_NAME_VMINSD, 0x5d, 3, 1, 0},
        {CDISASM_X86_NAME_VDIVPS, 0x5e, 0, 0, 0},
        {CDISASM_X86_NAME_VDIVPD, 0x5e, 1, 0, 0},
        {CDISASM_X86_NAME_VDIVSS, 0x5e, 2, 1, 0},
        {CDISASM_X86_NAME_VDIVSD, 0x5e, 3, 1, 0},
        {CDISASM_X86_NAME_VMAXPS, 0x5f, 0, 0, 0},
        {CDISASM_X86_NAME_VMAXPD, 0x5f, 1, 0, 0},
        {CDISASM_X86_NAME_VMAXSS, 0x5f, 2, 1, 0},
        {CDISASM_X86_NAME_VMAXSD, 0x5f, 3, 1, 0},
        {CDISASM_X86_NAME_VPCMPGTB, 0x64, 1, 0, 1},
        {CDISASM_X86_NAME_VPCMPGTW, 0x65, 1, 0, 1},
        {CDISASM_X86_NAME_VPCMPGTD, 0x66, 1, 0, 1},
        {CDISASM_X86_NAME_VPCMPEQB, 0x74, 1, 0, 1},
        {CDISASM_X86_NAME_VPCMPEQW, 0x75, 1, 0, 1},
        {CDISASM_X86_NAME_VPCMPEQD, 0x76, 1, 0, 1},
        {CDISASM_X86_NAME_VPADDQ, 0xd4, 1, 0, 1},
        {CDISASM_X86_NAME_VPMULLW, 0xd5, 1, 0, 1},
        {CDISASM_X86_NAME_VPMINUB, 0xda, 1, 0, 1},
        {CDISASM_X86_NAME_VPAND, 0xdb, 1, 0, 1},
        {CDISASM_X86_NAME_VPMAXUB, 0xde, 1, 0, 1},
        {CDISASM_X86_NAME_VPANDN, 0xdf, 1, 0, 1},
        {CDISASM_X86_NAME_VPAVGB, 0xe0, 1, 0, 1},
        {CDISASM_X86_NAME_VPAVGW, 0xe3, 1, 0, 1},
        {CDISASM_X86_NAME_VPMINSW, 0xea, 1, 0, 1},
        {CDISASM_X86_NAME_VPOR, 0xeb, 1, 0, 1},
        {CDISASM_X86_NAME_VPMAXSW, 0xee, 1, 0, 1},
        {CDISASM_X86_NAME_VPXOR, 0xef, 1, 0, 1},
        {CDISASM_X86_NAME_VPMULUDQ, 0xf4, 1, 0, 1},
        {CDISASM_X86_NAME_VPMADDWD, 0xf5, 1, 0, 1},
        {CDISASM_X86_NAME_VPSADBW, 0xf6, 1, 0, 1},
        {CDISASM_X86_NAME_VPSUBB, 0xf8, 1, 0, 1},
        {CDISASM_X86_NAME_VPSUBW, 0xf9, 1, 0, 1},
        {CDISASM_X86_NAME_VPSUBD, 0xfa, 1, 0, 1},
        {CDISASM_X86_NAME_VPSUBQ, 0xfb, 1, 0, 1},
        {CDISASM_X86_NAME_VPADDB, 0xfc, 1, 0, 1},
        {CDISASM_X86_NAME_VPADDW, 0xfd, 1, 0, 1},
        {CDISASM_X86_NAME_VPADDD, 0xfe, 1, 0, 1}
    };
    static const uint8_t memory[] = {
        0xc4, 0x01, 0x6c, 0x58, 0x4c, 0xac, 0x20
    };
    static const uint8_t extended_registers[] = {
        0xc4, 0x41, 0x2c, 0x58, 0xcb
    };
    static const uint8_t vex2_extended_destination[] = {
        0xc5, 0x68, 0x58, 0xcb
    };
    static const uint8_t scalar_l1[] = {0xc5, 0xee, 0x58, 0xcb};
    static const uint8_t integer_bad_pp[] = {0xc5, 0xe8, 0xfc, 0xcb};
    static const uint8_t truncated[] = {0xc5, 0xe8, 0x58};
    static const uint8_t non64_extension[] = {
        0xc4, 0xc1, 0x68, 0x58, 0xc0
    };
    static const uint8_t mode16_hidden_b[] = {
        0xc4, 0xc1, 0x68, 0x58, 0x00
    };
    static const uint8_t mode32_hidden_b_disp32[] = {
        0xc4, 0xc1, 0x68, 0x58, 0x0d, 0, 0, 0, 0
    };
    static const uint8_t mode32_hidden_b_sib[] = {
        0xc4, 0xc1, 0x68, 0x58, 0x04, 0x25, 0, 0, 0, 0
    };
    static const uint8_t mode16_no_extensions[] = {
        0xc4, 0xe1, 0x68, 0x58, 0x00
    };
    static const uint8_t mode32_no_extensions[] = {
        0xc4, 0xe1, 0x68, 0x58, 0x0d, 0, 0, 0, 0
    };
#if USE_EXTRA_OPCODES
    static const uint8_t wig_w1[] = {0xc4, 0xe1, 0xe8, 0x58, 0xcb};
    static const uint8_t avx2[] = {0xc5, 0xed, 0xfc, 0xcb};
#endif
    cdisasm_instruction instruction;
    size_t index;

    for (index = 0; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        uint8_t bytes[] = {0xc5, 0, 0, 0xcb};

        bytes[1] = (uint8_t)(0xe8u | cases[index].prefix);
        bytes[2] = cases[index].opcode;
#if USE_EXTRA_OPCODES
        EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
            bytes, sizeof(bytes), 0x1000,
            CDISASM_X86_TEST_ALL_FLAGS, &instruction) == sizeof(bytes));
        EXPECT(instruction.name_id == cases[index].name_id);
        EXPECT(instruction.operand_count == 3);
        EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_XMM1);
        EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_XMM2);
        EXPECT(instruction.opcode[2].reg == CDISASM_X86_REG_XMM3);
        EXPECT(instruction.opcode[0].access == CDISASM_OPERAND_ACCESS_WRITE);
        EXPECT(instruction.opcode[1].access == CDISASM_OPERAND_ACCESS_READ);
        EXPECT(instruction.opcode[2].access == CDISASM_OPERAND_ACCESS_READ);
        EXPECT(cdisasm_instruction_has_x86_group(
            &instruction, CDISASM_X86_GROUP_AVX));
        EXPECT(!cdisasm_instruction_has_x86_group(
            &instruction, CDISASM_X86_GROUP_AVX2));
#else
        EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
            bytes, sizeof(bytes), 0x1000,
            CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
        EXPECT(instruction.last_error_id
            == CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
#endif

        if (!cases[index].scalar) {
            bytes[1] |= UINT8_C(0x04);
#if USE_EXTRA_OPCODES
            EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
                bytes, sizeof(bytes), 0x1000,
                CDISASM_X86_TEST_ALL_FLAGS, &instruction)
                == sizeof(bytes));
            EXPECT(instruction.name_id == cases[index].name_id);
            EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_YMM1);
            EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_YMM2);
            EXPECT(instruction.opcode[2].reg == CDISASM_X86_REG_YMM3);
            EXPECT(cdisasm_instruction_has_x86_group(
                &instruction, CDISASM_X86_GROUP_AVX));
            EXPECT(cdisasm_instruction_has_x86_group(
                    &instruction, CDISASM_X86_GROUP_AVX2)
                == (cases[index].integer != 0));
#else
            EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
                bytes, sizeof(bytes), 0x1000,
                CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
            EXPECT(instruction.last_error_id
                == CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
#endif
        }
    }

#if USE_EXTRA_OPCODES
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        memory, sizeof(memory), 0x1000,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == sizeof(memory));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_VADDPS);
    EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_YMM9);
    EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_YMM2);
    EXPECT(instruction.opcode[2].type == CDISASM_OPERAND_MEMORY);
    EXPECT(instruction.opcode[2].size == 32);
    EXPECT(instruction.opcode[2].base_reg == CDISASM_X86_REG_R12);
    EXPECT(instruction.opcode[2].index_reg == CDISASM_X86_REG_R13);
    EXPECT(instruction.opcode[2].scale == 4);
    EXPECT(instruction.opcode[2].imm == 0x20);
    EXPECT(cdisasm_instruction_has_x86_group(
        &instruction, CDISASM_X86_GROUP_AMD64));
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        extended_registers, sizeof(extended_registers), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(extended_registers));
    EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_YMM9);
    EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_YMM10);
    EXPECT(instruction.opcode[2].reg == CDISASM_X86_REG_YMM11);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        vex2_extended_destination, sizeof(vex2_extended_destination), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(vex2_extended_destination));
    EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_XMM9);
    EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_XMM2);
    EXPECT(instruction.opcode[2].reg == CDISASM_X86_REG_XMM3);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_SANDY_BRIDGE,
        CDISASM_MODE_64, avx2, sizeof(avx2), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
    EXPECT(instruction.last_error_id == CDISASM_STATUS_INVALID_INSTRUCTION);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_HASWELL,
        CDISASM_MODE_64, avx2, sizeof(avx2), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == sizeof(avx2));
    EXPECT(cdisasm_instruction_has_x86_group(
        &instruction, CDISASM_X86_GROUP_AVX2));
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_SANDY_BRIDGE,
        CDISASM_MODE_64, wig_w1, sizeof(wig_w1), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == sizeof(wig_w1));
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_16,
        mode16_no_extensions, sizeof(mode16_no_extensions), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(mode16_no_extensions));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_VADDPS);
    EXPECT(instruction.opcode[2].base_reg == CDISASM_X86_REG_BX);
    EXPECT(instruction.opcode[2].index_reg == CDISASM_X86_REG_SI);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        mode32_no_extensions, sizeof(mode32_no_extensions), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction)
        == sizeof(mode32_no_extensions));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_VADDPS);
    EXPECT((instruction.opcode[2].flags & CDISASM_OPERAND_FLAG_ABSOLUTE)
        != 0);
#else
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        memory, sizeof(memory), 0x1000,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
    EXPECT(instruction.last_error_id
        == CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        extended_registers, sizeof(extended_registers), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
    EXPECT(instruction.last_error_id
        == CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        vex2_extended_destination, sizeof(vex2_extended_destination), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
    EXPECT(instruction.last_error_id
        == CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_16,
        mode16_no_extensions, sizeof(mode16_no_extensions), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
    EXPECT(instruction.last_error_id
        == CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_32,
        mode32_no_extensions, sizeof(mode32_no_extensions), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == 0);
    EXPECT(instruction.last_error_id
        == CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
#endif

#if USE_EXTRA_OPCODES
    EXPECT(cdisasm_x86_decode(CDISASM_CPU_X86, CDISASM_MODE_64,
        scalar_l1, sizeof(scalar_l1), 0,
        CDISASM_X86_TEST_ALL_FLAGS, &instruction) == sizeof(scalar_l1));
    EXPECT(instruction.name_id == CDISASM_X86_NAME_VADDSS);
    EXPECT(instruction.opcode[0].reg == CDISASM_X86_REG_XMM1);
    EXPECT(instruction.opcode[1].reg == CDISASM_X86_REG_XMM2);
    EXPECT(instruction.opcode[2].reg == CDISASM_X86_REG_XMM3);
#else
    expect_failure("disabled VEX scalar LIG", CDISASM_MODE_64,
        scalar_l1, sizeof(scalar_l1),
        CDISASM_STATUS_UNSUPPORTED_INSTRUCTION);
#endif
    expect_failure("VEX integer wrong pp", CDISASM_MODE_64,
        integer_bad_pp, sizeof(integer_bad_pp),
        CDISASM_STATUS_INVALID_INSTRUCTION);
    expect_failure("truncated VEX extra ModRM", CDISASM_MODE_64,
        truncated, sizeof(truncated), CDISASM_STATUS_TRUNCATED);
    expect_failure("VEX non-64 extension", CDISASM_MODE_32,
        non64_extension, sizeof(non64_extension),
        CDISASM_STATUS_INVALID_INSTRUCTION);
    expect_failure("VEX3 hidden B bit in mode 16", CDISASM_MODE_16,
        mode16_hidden_b, sizeof(mode16_hidden_b),
        CDISASM_STATUS_INVALID_INSTRUCTION);
    expect_failure("VEX3 hidden B bit in mode 32 disp32", CDISASM_MODE_32,
        mode32_hidden_b_disp32, sizeof(mode32_hidden_b_disp32),
        CDISASM_STATUS_INVALID_INSTRUCTION);
    expect_failure("VEX3 hidden B bit in mode 32 SIB", CDISASM_MODE_32,
        mode32_hidden_b_sib, sizeof(mode32_hidden_b_sib),
        CDISASM_STATUS_INVALID_INSTRUCTION);
}

int main(void)
{
    test_x86_reg_ids();
    test_x86_name_ids();
    test_x86_group_ids();
    test_metadata();
    test_decode_cases();
    test_failures_and_limits();
    test_decode();
    test_rex_w_prefix_metadata();
    test_x86_group_metadata();
    test_cpu_profiles();
    test_vex_zero_instructions();
    test_hle_prefix_semantics();
    test_sse_families();
    test_vex_extra_opcodes();
    test_x87_exhaustive_classification();
    test_x87_cpu_wait_and_metadata();

    if (failures != 0) {
        fprintf(stderr, "%d test expectation(s) failed\n", failures);
        return 1;
    }

    puts("all cdisasm tests passed");
    return 0;
}
